**Make loadNames(ids) concurrent**

`loadNames(ids)` returns the right names but fetches one user at a time. Make all the `getUser` calls run at once with `Promise.all`, keeping the names in the order of `ids`. Don't change `check` or `getUser`.

```js
// Test driver: don't change.
async function check(ids) {
  maxInFlight = 0;
  const names = await loadNames(ids);
  return { names, concurrent: ids.length < 2 || maxInFlight === ids.length };
}

async function loadNames(ids) {
  const names = [];
  for (const id of ids) {
    const user = await getUser(id);
    names.push(user.name);
  }
  return names;
}

// Fake API: don't change.
let inFlight = 0;
let maxInFlight = 0;
function getUser(id) {
  inFlight++;
  maxInFlight = Math.max(maxInFlight, inFlight);
  return new Promise((resolve) => {
    setTimeout(() => {
      inFlight--;
      resolve({ id, name: `user${id}` });
    }, 10);
  });
}
```

