**Fix getJson(url)**

`getJson(url)` returns the error page's body when the server answers 404 or 500. Throw `new Error(`HTTP ${status}`)` (e.g. `"HTTP 404"`) when the response isn't ok. Don't change the fake `fetch`.

```js
async function getJson(url) {
  const response = await fetch(url);
  return response.json();
}

// Fake server for the tests: don't change.
async function fetch(url) {
  const routes = {
    "/users/1": { status: 200, body: { id: 1, name: "Ada" } },
    "/down": { status: 500, body: { error: "server error" } },
  };
  const route = routes[url] ?? { status: 404, body: { error: "not found" } };
  return {
    ok: route.status >= 200 && route.status < 300,
    status: route.status,
    json: async () => route.body,
  };
}
```

notes.back:
// Why: An HTTP error is still a successful fetch: the promise resolves with the response.
// `response.ok` is true only for 200–299, so check it before reading the body.
// Docs: https://developer.mozilla.org/en-US/docs/Web/API/Window/fetch
async function getJson(url) {
  const response = await fetch(url);
  if (!response.ok) throw new Error(`HTTP ${response.status}`);
  return response.json();
}

